--- checkout ---
<template>
  <view class="checkout">
    <view bindtap="chooseAddress">选择地址</view>
    <view wx:if="{{address}}">{{address.name}} {{address.detail}}</view>
    <button bindtap="pay">支付</button>
    <button bindtap="openOrders">查看订单</button>
  </view>
</template>

<script>
import mpx, { createPage } from '@mpxjs/core'

createPage({
  data: { address: null },
  methods: {
    chooseAddress () {
      mpx.navigateTo({
        url: '/pages/address/select',
        events: {
          acceptDataFromOpenedPage: (address) => {
            this.address = address
          }
        }
      })
    },
    pay () {
      mpx.redirectTo({ url: '/pages/pay/result' })
    },
    openOrders () {
      mpx.switchTab({ url: '/pages/orders/index' })
    },
    requireLogin () {
      mpx.reLaunch({ url: '/pages/login/index' })
    }
  }
})
</script>

--- address ---
<template>
  <view>
    <view wx:for="{{addresses}}" wx:key="id" bindtap="confirm(item)">{{item.name}} {{item.detail}}</view>
  </view>
</template>

<script>
import mpx, { createPage } from '@mpxjs/core'

createPage({
  data: {
    addresses: [
      { id: 'home', name: '家', detail: '幸福路 1 号' },
      { id: 'office', name: '公司', detail: '科技路 8 号' }
    ]
  },
  onLoad () {
    this.eventChannel = this.getOpenerEventChannel && this.getOpenerEventChannel()
  },
  methods: {
    confirm (address) {
      if (this.eventChannel && this.eventChannel.emit) {
        this.eventChannel.emit('acceptDataFromOpenedPage', address)
      }
      mpx.navigateBack({ delta: 1 })
    }
  }
})
</script>

